  "noticeText": "Cook は、ご利用の料理機能とログイン機能のためにブラウザーストレージを使用します。広告や分析のためのストレージは追加しません。",
  "noticeClose": "ストレージのお知らせを閉じる",
  "privDraftLabel": "草案 — 2026年10月28日更新。",
  "privDraft": "アカウント機能は現在テスト中です。以下の運営者およびサービスの情報は、一般公開前に記入する必要があります。",
  "privWho1": "Cook の運営者は［運営者の正式名称と郵便宛先］です。プライバシーに関するご質問やご請求は［プライバシー用メールアドレス］までご連絡ください。これらの情報は登録受付の開始前に記入する必要があります。",
  "privWhat1": "アカウントを作成すると、アカウントの提供と保護のために、メールアドレス、アカウント識別子、パスワード認証の記録、確認状況を使用します。パスワードは認証プロバイダーが安全なハッシュとして扱い、Cook は読み取り可能なパスワードを保存しません。すべての端末で設定を復元するため、キッチンの配置、選択した言語、テーマ、計量単位を保存します。アカウントにはメールアドレスとパスワードが必要ですが、レシピはアカウントなしでも閲覧できます。",
  "privWhat2": "アカウントと設定の処理は、お客様が求めるアカウントサービスの提供に必要です（GDPR 第6条第1項(b)）。セキュリティおよび不正利用防止のための限られた記録は、必要性と利益衡量を条件に、正当な利益（第6条第1項(f)）に基づいて処理される場合があります。確認メールとパスワードリセットのメールはサービス上の連絡であり、マーケティングではありません。アカウント機能によって広告や分析が追加されることはありません。",
  "privStorage1": "Cook は sessionStorage を使用して、同じタブ内のページ間でキッチン、調理の進行状況、選択内容を引き継ぎます。ログイン中は認証セッションも保持します。通常、タブのセッションが終了するとブラウザーがこれを消去しますが、ブラウザーのセッション復元機能によって残る場合があります。ログアウトすると Cook のタブデータは消去されます。ストレージのお知らせを閉じた状態は、そのタブでのみ記憶されます。Cook 自身のスクリプトは Cookie を設定しません。ホスティングやサービスの提供者が独自にセキュリティ処理を行う場合があり、公開前に文書化する必要があります。",
  "privStorage2": "ストレージのお知らせの「OK」と閉じるボタンは、お知らせを閉じるだけです。分析、広告、その他の任意のトラッキングを許可するものではありません。今後、必須ではないストレージを使う場合は、開始前に別途選択していただき、拒否と撤回も同じく簡単に行えるようにします。",
  "privOther1": "現在のレシピ一覧の音声機能は、音声認識の言語を選ぶために、IP アドレスをもとに country.is へおおよその国を問い合わせます。マイクによる認識を使う場合、ブラウザーが音声をそのブラウザーの音声認識サービス提供者に送信することがあります。材料は文字で入力することもできます。これらの提供者、そのポリシー、およびこれらの機能の法的根拠は、一般公開前に確認する必要があります。",
  "privProviders1": "予定しているアカウント提供者：Supabase（マネージド PostgreSQL と認証）、EU 内で選択したデータベースリージョンを使用。メール提供者：［提供者］。ウェブサイトのホスティング：［提供者］。運営者は、実際の提供者、処理契約、再委託先、ログの保存場所、EEA 外への移転の有無を確認する必要があります。EU のデータベースリージョンであっても、それだけで国際的な移転がないとは言えません。該当する場合は、適用される十分性認定または契約上の保護措置と、その写しの入手方法を明示してください。",
  "privRetention1": "アカウントの設定は、アカウントが有効な間保存されます。削除は上記のプライバシー窓口に請求できます。公開前に運営者は、削除請求への対応手順、未確認アカウントの有効期限、セキュリティログとバックアップの保存期間を定める必要があります。削除したデータは、文書化されたバックアップ保存期間が終わるまで、アクセスが制限されたバックアップに残る場合があります。",
  "privRights1": "適用される条件に応じて、アクセス、訂正、削除、処理の制限、データポータビリティを請求したり、正当な利益に基づく処理に異議を述べたりできます。上記の運営者にご連絡ください。請求には通常1か月以内に回答し、法令に基づき延長する場合はその理由をご説明します。ハンガリーの NAIH（naih.hu）を含む監督機関に苦情を申し立てることができます。Cook は、法的効果またはそれと同様の重大な影響を生じる自動化された意思決定にアカウント設定を使用しません。",
