  "Boil down": "煮詰める",
  "Let it boil until the water level roughly matches the rice level.": "水位が米の高さとほぼ同じになるまで沸騰させる。",
  "Water level at the rice": "水位が米の高さ",
  "Cover, lowest heat": "ふたをしてごく弱火",
  "Set the lowest heat and cover. Don't stir or lift the lid.": "いちばん弱い火にしてふたをする。混ぜたりふたを開けたりしない。",
  "Time is up": "時間になった",
  "Rest, covered": "ふたをしたまま蒸らす",
