  "Rested": "蒸らした",
  "Julienne the vegetables": "野菜をせん切りにする",
  "Cut the carrot, the cucumber (easy option) and the white part of the green onions into matchsticks. Chop the green parts for topping.": "にんじん、きゅうり（簡単バージョン）、青ねぎの白い部分を細切りにする。緑の部分はトッピング用に刻む。",
  "Matchstick-sized": "マッチ棒くらいの太さ",
  "Prepare the bok choy": "チンゲン菜を準備する",
  "Tear the bok choy apart by leaves and wash it thoroughly.": "チンゲン菜を1枚ずつはがし、よく洗う。",
  "Clean leaves": "葉がきれい",
  "Mix the sauce": "ソースを混ぜる",
  "Mix the gochujang, sesame oil, sugar or honey, rice vinegar, water, sesame seeds and grated garlic.": "コチュジャン、ごま油、砂糖またははちみつ、米酢、水、ごま、すりおろしたにんにくを混ぜる。",
  "Smooth sauce": "なめらかなソース",
  "Chicken into the pan": "鶏肉をフライパンへ",
  "Heat a large pan on medium-high with a little oil. Add the marinated chicken.": "大きなフライパンに油を少しひいて中強火で熱し、漬けた鶏肉を入れる。",
  "Chicken spread out": "鶏肉が広がっている",
  "Stir-fry the chicken": "鶏肉を炒める",
  "Stir-fry until done.": "火が通るまで炒める。",
  "No pink inside": "中に赤みがない",
  "Chicken out": "鶏肉を取り出す",
  "Take the chicken out of the pan.": "鶏肉をフライパンから取り出す。",
  "Chicken set aside": "鶏肉を取り分けた",
  "Water and oil in the pan": "フライパンに水と油",
  "Clean the pan (or use another). While cold, add a few tbsp of water and a few tsp of oil, then heat it.": "フライパンをきれいにする（または別のものを使う）。冷たいうちに水を大さじ数杯と油を小さじ数杯入れてから熱する。",
  "Hot and steaming": "熱くて湯気が立つ",
  "Steam-fry the bok choy": "チンゲン菜を蒸し炒めにする",
  "Add the bok choy with a little salt, stirring. Don't overcook it.": "チンゲン菜と塩少々を入れ、混ぜながら炒める。火を通しすぎない。",
  "Just wilted, still green": "しんなりしたばかりで、まだ緑",
  "Fry the eggs": "目玉焼きを焼く",
  "Fry the eggs sunny side up in a small pan with a little oil, one at a time. Keep the yolk a little runny, salt a tiny bit, add a splash of sesame oil near the end.": "小さなフライパンに油を少しひき、卵を1個ずつ目玉焼きにする。黄身は少しとろりと残し、塩をほんの少しふり、最後にごま油をひとたらし。",
  "White set, yolk runny": "白身が固まり、黄身はとろり",
  "Plate it": "盛り付ける",
  "Rice first, the chicken next to it, the bok choy next to it, then the vegetables and the egg on top. Drizzle light soy sauce, add the green onion greens, 1 tsp of sauce and the sesame seeds.": "まずごはん、その横に鶏肉、その横にチンゲン菜、そして上に野菜と卵をのせる。薄口しょうゆをかけ、青ねぎの緑の部分、ソース小さじ1、ごまをのせる。",
  "Toast the rice … Rest, covered": "米を炒る … ふたをしたまま蒸らす",
  "Mix the sauce · Plate it": "ソースを混ぜる · 盛り付ける",
  "Chicken into the pan … Steam-fry the bok choy": "鶏肉をフライパンへ … チンゲン菜を蒸し炒めにする",
  "Shred and salt the cucumber": "きゅうりを細切りにして塩をふる",
  "Shred the cucumber, add a pinch of salt.": "きゅうりを細切りにし、塩をひとつまみふる。",
  "Shredded, salted": "細切りにして塩をふった",
  "Let the cucumber rest": "きゅうりを置く",
  "Let it rest.": "そのまま置いておく。",
  "Squeeze the cucumber": "きゅうりを絞る",
  "Squeeze the water out.": "水気を絞る。",
  "Dry-ish": "ほぼ水気がない",
  "Sauté the carrot": "にんじんを炒める",
  "Sauté the julienned carrot for about 1 minute.": "細切りにしたにんじんを約1分炒める。",
  "Slightly soft": "少しやわらかい",
  "Shred and salt the cucumber · Let the cucumber rest": "きゅうりを細切りにして塩をふる · きゅうりを置く",
  "Squeeze the cucumber · Prepare the bok choy": "きゅうりを絞る · チンゲン菜を準備する",
  "Chicken into the pan … Sauté the carrot": "鶏肉をフライパンへ … にんじんを炒める",
  "Cut the chicken breast into chunks (about 3 cm).": "鶏むね肉をひと口大（約3 cm）に切る。",
  "Add the chicken to a container with a little oil, salt, mustard, honey, tarragon, the white wine (or stock + lemon juice), black pepper and a very small amount of MSG. Mix well and cover.": "容器に鶏肉、油少々、塩、マスタード、はちみつ、タラゴン、白ワイン（またはブイヨン＋レモン汁）、黒こしょう、ごく少量のうま味調味料を入れる。よく混ぜてふたをする。",
  "About 1 hour passed": "約1時間たった",
  "Peel and dice the onion.": "玉ねぎの皮をむいて角切りにする。",
  "Diced": "角切りにした",
  "Dice the garlic": "にんにくを角切りにする",
  "Peel and dice the garlic.": "にんにくの皮をむいて細かく切る。",
  "Slice the mushrooms": "マッシュルームを薄切りにする",
  "Slice the white mushrooms.": "マッシュルームを薄切りにする。",
  "Sliced": "薄切りにした",
