  "Onion into the pan": "玉ねぎをフライパンへ",
  "Heat a little oil in the pan and add the onion.": "フライパンに油を少し熱し、玉ねぎを入れる。",
  "Onion sizzling": "玉ねぎがジュージューいっている",
  "Fry the onion": "玉ねぎを炒める",
  "Fry for a couple of minutes.": "数分炒める。",
  "Softening": "しんなりしてきた",
  "Add the garlic and fry until glassy and fragrant.": "にんにくを加え、透き通って香りが立つまで炒める。",
  "Glassy, fragrant": "透き通り、香りが立つ",
  "Mushrooms in": "マッシュルームを入れる",
