  "Largest chunk white all the way through": "いちばん大きな肉の中まで白い",
  "Taste and finish": "味見して仕上げる",
  "Taste and adjust. Add the paprika and a little lemon juice and cook a bit more, stirring.": "味見をして調える。パプリカパウダーとレモン汁少々を加え、混ぜながらもう少し煮る。",
  "Rice first, then the chicken and mushrooms next to it. Sprinkle dried parsley on top.": "まずごはん、その横に鶏肉とマッシュルームを盛る。上に乾燥パセリをふる。",
  "Dice the chicken … Slice the mushrooms": "鶏肉を角切りにする … マッシュルームを薄切りにする",
  "Bring to a boil … Rest, covered": "沸騰させる … ふたをしたまま蒸らす",
