  "see Homemade Mayonnaise": "自家製マヨネーズを参照",
  "Make the mayonnaise": "マヨネーズを作る",
  "Make the mayonnaise from the Homemade Mayonnaise recipe (about 2 tbsp per person is needed).": "自家製マヨネーズのレシピでマヨネーズを作る（1人あたり大さじ約2が必要）。",
  "Thick mayonnaise": "もったりしたマヨネーズ",
  "Wash the lettuce": "レタスを洗う",
