  "Pat the chicken dry": "鶏肉の水気をふく",
  "Take the chicken out, pat it dry with paper towel (throw it away right away).": "鶏肉を取り出し、キッチンペーパーで水気をふく（ペーパーはすぐに捨てる）。",
  "Dry surface": "表面が乾いている",
  "Halve thick fillets": "厚い肉を半分にする",
