  "Add the lettuce. Scatter the chicken cubes, the parmesan and the croutons on it. Sprinkle a little Worcestershire sauce and add some mayonnaise on top.": "レタスを入れる。鶏肉、パルメザン、クルトンを散らす。ウスターソースを少しふり、マヨネーズをのせる。",
