  "Every cup lined": "すべてのカップに敷いた",
  "Eggs in": "卵を入れる",
  "Crack one egg into each cup (whisked option: break it up with a fork). Add salt and pepper. Cups should be about half full: it puffs up while baking.": "各カップに卵を1個ずつ割り入れる（溶き卵の場合はフォークでほぐす）。塩とこしょうをふる。焼くとふくらむので、カップは半分くらいまでにする。",
