  "All cups filled": "すべてのカップに入れた",
  "Bake": "焼く",
  "Bake until the top is slightly browned and the center is set and doesn't wobble. Whole egg with runny yolk: start checking at 12 to 14 min.": "表面にうっすら焼き色がつき、中心が固まって揺れなくなるまで焼く。黄身をとろりとさせる全卵の場合は、12〜14分から様子を見る。",
