  "Thin ribbons": "薄いリボン状",
  "Cucumber ribbons": "きゅうりのリボン",
  "Peel ribbons from all sides of the unpeeled cucumber, skin included. Stop at the seedy core.": "皮をむかないきゅうりを、皮ごと四方からリボン状にむく。種のある芯で止める。",
