  "Even sauce": "均一なソース",
  "Spread and top": "塗って具をのせる",
  "Spread the pizza sauce (or sour cream) on each tortilla, leaving about 1 cm at the edge. Add the toppings: ham and cheese (or bacon, garlic, red onion and cheese).": "各トルティーヤにピザソース（またはサワークリーム）を塗り、縁を約1 cm残す。具をのせる：ハムとチーズ（またはベーコン、にんにく、赤玉ねぎ、チーズ）。",
